<?php require __DIR__.'/inc/page_helpers.php'; $games=$db->query("SELECT id,title,description,visits FROM games ORDER BY visits DESC LIMIT 8")->fetchAll(); page_start('Home'); ?><section id="SplashContainer"><aside id="SignInPane"><?php if($currentUser):?><h2>Welcome, <?=e($currentUser['username'])?></h2><a class="Button" href="/My/Home.php">My ROBLOX</a><?php else:?><h2>Member Login</h2><form method="post" action="/Login.php"><label>Character Name<input name="username" required></label><label>Password<input type="password" name="password" required></label><button class="Button">Login</button></form><a href="/Register.php">Register for free</a><?php endif;?></aside><div id="RobloxAtAGlance"><h1>ROBLOX Virtual Playworld</h1><h2>Build. Play. Share.</h2><p>Explore places, meet friends and discover player creations.</p></div></section><section class="Panel"><h2>Cool Places</h2><div class="tile-grid"><?php foreach($games as $g):?><article class="tile"><a href="/PlaceItem.php?id=<?=(int)$g['id']?>"><?=e($g['title'])?></a><p><?=e($g['description'])?></p></article><?php endforeach;?><?php if(!$games):?><p>No places have been added yet.</p><?php endif;?></div></section><?php page_end();